in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos=vec4(a_position,1);
  #if USE_LOCAL
    pos=cc_matWorld*pos;
  #endif
  uv0=a_texCoord;
  #if SAMPLE_FROM_RT
    uv0 = cc_cameraPos.w > 1.0 ? vec2(uv0.x, 1.0 - uv0.y) : uv0;
  #endif
  color=a_color;
  return cc_matViewProj*pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform TerrainStyle { vec4 terrainStyle; };
vec3 spritePalette(vec3 rgb) {
  float light=dot(rgb,vec3(0.299,0.587,0.114));
  float steps=6.0;
  float level=floor(clamp(light,0.0,0.999)*steps)/(steps-1.0);
  vec3 dark=vec3(0.22,0.20,0.18), bright=vec3(0.77,0.70,0.55);
  if(rgb.g>rgb.r*1.08 && rgb.g>rgb.b*1.13){dark=vec3(0.14,0.27,0.20);bright=vec3(0.66,0.76,0.44);}
  else if(rgb.b>rgb.r*1.18 && rgb.b>rgb.g*0.95){dark=vec3(0.13,0.25,0.34);bright=vec3(0.49,0.74,0.76);}
  else if(rgb.r>rgb.g*1.8){dark=vec3(0.29,0.16,0.17);bright=vec3(0.82,0.46,0.30);}
  else if(rgb.r>rgb.b*1.35){dark=vec3(0.29,0.23,0.18);bright=vec3(0.83,0.67,0.42);}
  vec3 result=mix(dark,bright,level);
  if(terrainStyle.w>2.5){
    if(rgb.g>rgb.r*1.08 && rgb.g>rgb.b*1.13)result=mix(vec3(0.36,0.46,0.28),result,0.28);
    else if(rgb.r>rgb.b*1.35 && rgb.r<rgb.g*1.8)result=mix(vec3(0.51,0.40,0.27),result,0.40);
  }else if(light<0.24)return vec3(0.12,0.14,0.17);
  return result;
}
vec4 frag () {
  vec2 size=terrainStyle.xy;
  vec2 pixel=uv0*size,center;
  float tileId=floor(pixel.y/36.0)*8.0+floor(pixel.x/36.0);
  float block=terrainStyle.w;
  if(pixel.y<288.0 && (abs(tileId-2.0)<0.1||abs(tileId-14.0)<0.1||abs(tileId-54.0)<0.1))block=2.0;
  if(block>2.5 && pixel.y<288.0){vec2 origin=floor(pixel/36.0)*36.0+2.0;center=origin+clamp(floor((pixel-origin)/block)*block+block*0.5,vec2(2.0),vec2(30.0));}
  else center=floor(pixel/block)*block+block*0.5;
  center/=size;
  vec2 halfPixel=vec2(block*0.5-0.5)/size;
  vec4 o=(CCSampleWithAlphaSeparated(cc_spriteTexture,center-halfPixel)
    +CCSampleWithAlphaSeparated(cc_spriteTexture,center+halfPixel)
    +CCSampleWithAlphaSeparated(cc_spriteTexture,center+vec2(halfPixel.x,-halfPixel.y))
    +CCSampleWithAlphaSeparated(cc_spriteTexture,center+vec2(-halfPixel.x,halfPixel.y)))*0.25;
  if(terrainStyle.z>0.5 && terrainStyle.z<1.5 && o.b>0.15 && o.b>o.r*1.3 && o.b>o.g*1.05)discard;
  if(terrainStyle.z>1.5 && o.g>o.r*1.06 && o.g>o.b*1.10)discard;
  o.rgb=spritePalette(o.rgb);
  if(terrainStyle.w>2.5 && pixel.y<288.0){
    if(abs(tileId)<0.1)o.rgb*=vec3(0.85,0.92,0.88);
    if(abs(tileId-18.0)<0.1)o.rgb*=0.78;
    if(abs(tileId-19.0)<0.1)o.rgb=mix(o.rgb,vec3(0.38,0.58,0.54),0.22);
    if(abs(tileId-7.0)<0.1||abs(tileId-61.0)<0.1)o.rgb*=0.65;
  }
  o*=color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

